    # Case 1: R={1}, B={}. Triples must be in R^3.
    R = {1}
    B = set()

    count_R = 0
    for x in R:
        for y in R:
            for z in R:
                if (x + y + z) % n == 0:
                    count_R += 1

    count_B = 0
    for x in B:
        for y in B:
            for z in B:
                if (x + y + z) % n == 0:
                    count_B += 1

    total_count = count_R + count_B

    print(f"For n={n}, the maximum possible count is {total_count}.")
